--
-- Structure for view `active_sessions`
--
DROP TABLE IF EXISTS `active_sessions`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u724930382_yamanstore`@`127.0.0.1` SQL SECURITY DEFINER VIEW `active_sessions`  AS SELECT `sl`.`user_id` AS `user_id`, `u`.`username` AS `username`, `u`.`full_name` AS `full_name`, `sl`.`session_id` AS `session_id`, `sl`.`ip_address` AS `ip_address`, `sl`.`created_at` AS `login_time`, timestampdiff(MINUTE,`sl`.`created_at`,current_timestamp()) AS `session_duration_minutes` FROM (`session_logs` `sl` join `users` `u` on(`sl`.`user_id` = `u`.`id`)) WHERE `sl`.`action` = 'login' AND exists(select 1 from `session_logs` `sl2` where `sl2`.`user_id` = `sl`.`user_id` AND `sl2`.`session_id` = `sl`.`session_id` AND `sl2`.`action` in ('logout','timeout') AND `sl2`.`created_at` > `sl`.`created_at` limit 1) is false AND `sl`.`created_at` > current_timestamp() - interval 2 hour ORDER BY `sl`.`created_at` DESC ;

