INSERT INTO `whatsapp_template` (`id`, `name`, `message_content`, `target_event`, `is_active`, `created_at`, `updated_at`) VALUES
(3, 'إشعار طلب جديد للإدارة', '*🔔 تنبيه | طلب جديد بانتظار المراجعة*\r\n\r\nالرجاء مراجعة و تأكيد الطلب التالي:\r\n \r\n\r\n○ تــــــاريخ الطـــــــلب: {order_date}\r\n○ عـــــــــــدد القطـــــع: {order_quantity}\r\n\r\n○ الإجمالي قبل الخصم: {gross_total}\r\n○ الإجمالي بعد ا لخصم: {order_total}\r\n○ الخصــ({discount_percentage}%)ـــــــم: {discount_amount}\r\n○ المبلــــــغ المدفـــــوع: {payment_amount}\r\n○ المبلــــــغ المتبـقـــــي: {remaining_amount}\r\n\r\n◾️ رابط الكـــل ◾️\r\n{order_link}\r\n\r\n\r\n\r\n◾️ المكــــــرر ◾️\r\n{additional_link}', 'order_created_admin', 1, '2026-03-15 22:56:12', '2026-03-23 07:09:36'),
(4, 'إشعار طلب جديد من البوابة (Checkout)', 'مرحباً،\r\nلدي طلب جديد من البوابة.\r\n\r\n*الاسم:* {{customer-name}}\r\n*رقم الطلب:* {{order-number}}\r\n*الإجمالي:* {{total-amount}} {{currency}}\r\n\r\nيرجى مراجعة واعتماد الطلب في النظام.', 'checkout_order_created_admin', 1, '2026-04-17 16:03:43', '2026-04-17 16:11:04');
INSERT INTO `whatsapp_templates` (`id`, `template_name`, `template_content`, `category`, `variables`, `is_active`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'تأكيد استلام الطلب', 'مرحباً {customer_name} 👋\n\nتم استلام طلبك رقم {order_number} بنجاح ✅\n\nالمبلغ الإجمالي: {order_total}\n\nسيتم التواصل معك قريباً لتأكيد التفاصيل.\n\nشكراً لثقتك بنا 🌟', 'order', '{customer_name}, {order_number}, {order_total}', 0, 1, '2025-10-16 02:53:05', '2025-12-14 19:29:49'),
(2, 'تحديث حالة الطلب', 'عزيزي {customer_name} 👋\n\nطلبك رقم {order_number} الآن قيد التجهيز 📦\n\nسيتم الشحن خلال 24-48 ساعة.\n\nشكراً لانتظارك 🙏', 'order', '{customer_name}, {order_number}', 0, 1, '2025-10-16 02:53:05', '2025-12-14 19:30:08'),
(3, 'تأكيد الشحن', 'مرحباً {customer_name} 🚚\n\nتم شحن طلبك رقم {order_number}\n\nرقم التتبع: {tracking_number}\n\nسيصلك الطلب خلال 2-3 أيام عمل.\n\nنتمنى لك تجربة رائعة! 🌟', 'shipping', '{customer_name}, {order_number}, {tracking_number}', 0, 1, '2025-10-16 02:53:05', '2025-12-14 19:32:05'),
(4, 'تأكيد استلام الدفعة', 'عزيزي {customer_name} 💰\n\nتم استلام دفعتك بنجاح ✅\n\nالمبلغ المدفوع: {payment_amount}\n\nالمبلغ المتبقي: {remaining_amount}\n\nشكراً لك 🙏', 'payment', '{customer_name}, {payment_amount}, {remaining_amount}', 0, 1, '2025-10-16 02:53:05', '2025-12-14 19:31:18'),
(5, 'تذكير بالدفع', 'مرحباً {customer_name} 👋\n\nنذكرك بوجود مبلغ متبقي على طلبك رقم {order_number}\n\nالمبلغ المتبقي: {remaining_amount}\n\nيرجى التواصل معنا لترتيب الدفع.\n\nشكراً لتعاونك 🙏', 'payment', '{customer_name}, {order_number}, {remaining_amount}', 0, 1, '2025-10-16 02:53:05', '2025-12-14 19:31:59'),
(6, 'رسالة ترحيبية', 'أهلاً وسهلاً {customer_name} 🌟\n\nنشكرك على التواصل مع {company_name}\n\nنحن هنا لخدمتك على مدار الساعة.\n\nكيف يمكننا مساعدتك اليوم؟ 😊', 'general', '{customer_name}, {company_name}', 0, 1, '2025-10-16 02:53:05', '2025-12-14 19:32:14'),
(7, 'شكر بعد التسليم', 'عزيزي {customer_name} 🎉\n\nنأمل أن تكون قد استلمت طلبك بحالة ممتازة!\n\nرأيك يهمنا، يرجى تقييم تجربتك معنا.\n\nنتطلع لخدمتك مجدداً 🌟', 'general', '{customer_name}', 1, 1, '2025-10-16 02:53:05', '2025-10-16 02:53:05'),
(8, 'تم تعديل الطلب ', 'عملينا العزيز {customer_name} ان طلبك الخاص  {order_number} قد تم تعديله  والمبلغ المتبقي لديك هو {remaining_amount}', 'order', '', 0, 1, '2025-11-03 17:29:06', '2025-12-14 19:30:48'),
(9, 'المبلغ المتبقي ', 'المبلغ المتبقي {remaining_amount}', 'order', 'remaining_amount', 0, 1, '2025-12-03 01:14:21', '2025-12-14 19:29:31'),
(10, 'يي', '{customer_name}\r\n{order_number}\r\n{order_total}\r\n{order_date}\r\n{order_quantity}\r\n{tracking_number}\r\n{payment_amount}\r\n{remaining_amount}\r\n', 'order', '{customer_name} {order_number} {order_total} {order_date} {order_quantity} {tracking_number} {payment_amount} {remaining_amount}', 0, 1, '2025-12-03 21:05:43', '2025-12-14 19:30:53'),
(11, 'تجربة الرسائل', '{customer_name}\r\nاسم العميل\r\n\r\n{order_number}\r\nرقم الطلب\r\n\r\n{order_total}\r\nإجمالي الطلب\r\n\r\n{order_date}\r\nتاريخ الطلب\r\n\r\n{order_quantity}\r\nعدد القطع في الطلب\r\n\r\n{tracking_number}\r\nرقم التتبع\r\n\r\n{payment_amount}\r\nالمبلغ المدفوع\r\n\r\n{remaining_amount}\r\nالمبلغ المتبقي\r\n\r\n{company_name}\r\nاسم الشركة\r\n\r\n{account_portal}\r\nرابط بوابة حساب العميل', 'order', '', 0, 1, '2025-12-10 19:57:49', '2025-12-14 19:29:53'),
(12, 'اعتماد الطلب ', '✅ تم اعتماد طلبك بنجاح ✅\r\n رقم الطلب: ( {order_number} )\r\n\r\nعميلنا العزيز: {customer_name}\r\nيمكنك متابعة حالة طلبك آليًا وفي أي وقت عبر رابط حسابك في متجرنا، للاطلاع على تفاصيل الطلبات وحالتها خطوة بخطوة 🔍\r\n\r\n🔗 رابط حسابك وطلباتك: {account_portal}\r\n\r\n┈──────────────┈\r\n┈── يمــــ شي إن ـــــان ──┈\r\nحيث الأناقة تبدأ… والثقة لا تنتهي ', 'order', '', 0, 1, '2025-12-14 19:23:23', '2025-12-31 03:22:56'),
(13, 'تم اعتماد الطلب', '✅ تم اعتماد طلبك بنجاح ✅\r\n\r\nرقم الطلب: {order_number}\r\n\r\n🔗 لمتابعة حالة طلبك وتفاصيله عبر رابط حسابك في متجرنا: {account_portal}\r\n', 'order', '', 1, 1, '2025-12-31 01:08:20', '2025-12-31 01:10:11'),
(14, 'القطع المنتهيه', 'اشعار هام 💢\r\n\r\nعميلنا العزيز: {customer_name}\r\nنود إعلامك بانتهاء ( ) قطع من طلبك رقم ( {order_number} )\r\n\r\nنرفق لك صور القطع المنتهية من طلبك، والتي تم خصم قيمتها من إجمالي المبلغ.\r\n\r\n\r\nكما يمكنك تتبع التعديلات آلياً من خلال رابط حسابك في متجرنا.\r\n\r\n{account_portal}', 'order', '', 1, 1, '2025-12-31 01:50:59', '2026-01-09 21:27:19'),
(15, 'اشعار الدفعات ( سند دفع )', 'سند سداد إلكتروني 💰\r\n\r\nعميلنا العزيز: {customer_name}\r\nتم خصم المبلغ الذي تم إيداعه كجزء من سداد طلبك رقم ( {order_number} )\r\n\r\nالمبلغ المتبقي للدفع: {remaining_amount}\r\n\r\nيمكنك متابعة تحديثات الطلب و دفعات حسابك من خلال صفحة طلباتك على موقع المتجر.\r\n', 'order', '', 0, 1, '2025-12-31 02:00:37', '2025-12-31 02:44:09'),
(16, 'الطلب جاهز للتوصيل ', '📦 طلبك جاهز للتوصيل 📦\r\n\r\nعميلنا العزيز: {customer_name}\r\n\r\nطلبك رقم ( {order_number} ) أصبح جاهزاً للتوصيل\r\nالمبلغ المتبقي للدفع: {remaining_amount}\r\n\r\nرقم مندوب التوصيل: 784886887\r\nسيتواصل معك المندوب قريباً لتنسيق الاستلام، يرجى إبقاء الهاتف متاحاً.\r\n\r\nسيتم التوصيل اليوم أو غداً حسب جهة التوصيل\r\nشاكرين تعاونكم، ودمتم أصدقاءنا\r\n\r\n📍 يرجى تزويدنا بأي تحديث يخص موقع الاستلام قبل انطلاق المندوب.', 'order', '', 1, 1, '2025-12-31 02:15:19', '2026-05-09 20:08:36'),
(17, 'الدفعات ( سند دفع )', 'سند سداد إلكتروني 💰\r\n\r\nعميلنا العزيز: {customer_name}\r\nتم خصم المبلغ الذي تم إيداعه كجزء من سداد طلبك رقم ( {order_number} )\r\n\r\nالمبلغ المتبقي للدفع: {remaining_amount}\r\n\r\nيمكنك متابعة تحديثات الطلب و دفعات حسابك من خلال صفحة طلباتك على موقع المتجر.\r\n', 'order', '', 1, 1, '2025-12-31 02:22:53', '2025-12-31 03:22:07'),
(18, 'الطلب جاهز للتوصيل  ( محافظات )', 'طلبك أصبح جاهز للتوصيل 📦\r\n\r\nعميلنا العزيز: {customer_name}\r\nطلبك رقم ( {order_number} ) أصبح جاهزاً للتوصيل\r\nالمبلغ المتبقي للدفع: {remaining_amount}\r\n\r\nيرجى إيداع المبلغ المتبقي من حساب طلبكم ليتم شحنه في أسرع وقت.\r\n\r\nيرجى إبلاغنا بأي تحديث في موقع الاستلام\r\n', 'order', '', 1, 1, '2025-12-31 02:48:02', '2025-12-31 02:48:02'),
(19, 'تصفية الحساب', 'إشعار تصفية الحساب ❗️\r\n\r\nعميلنا العزيز: {customer_name}\r\nنود تذكيركم\r\nبضرورة تسديد المبلغ المتبقي عليكم: {remaining_amount}\r\nلإتمـــام حســــاب الطلـــــب رقـــــــم: {order_number}\r\n\r\nلضمان استمرارية تقديم خدماتنا لكم نرجو سرعة السداد.\r\n\r\n  🌸 شاكرين تعاونكم ودمتم اصدقائنا 🌸', 'order', '', 1, 1, '2025-12-31 03:12:36', '2025-12-31 03:12:36'),
(20, 'القطع الناقصه/التالفه', 'عميلنا العزيز: {customer_name}\r\n\r\nنود إعلامكم بأن طلبكم تأثر بظروف خارجة عن إرادتنا، نتج عنها فقدان بعض القطع بسبب إشكاليات جمركية وتعقيدات النقل الحالية.\r\n\r\n(   ) قطع ناقصة/تالفــة ضمن طلبك رقم ( {order_number} ).\r\nنرفق لك صور القطع الناقصة أو التالفة من طلبك، والتي تم خصم قيمتها من إجمالي المبلغ.\r\n\r\nكما يمكنك تتبع التعديلات آلياً من خلال رابط حسابك في متجرنا.', 'order', '', 1, 1, '2026-01-01 09:15:48', '2026-01-01 09:15:48'),
(21, 'استرداد المال ', 'عميلنا العزيز: {customer_name}\r\n\r\nتم تحديث حالة طلبك رقم ( {order_number} ) إلى \"قيد التجهيز والشحن\".\r\n\r\nملاحظة هامة: تم استبعاد (  ) قطعة من طلبك (مرفق صورها) للأسباب التالية:\r\n\r\n1. رفض المورد (SHEIN) شحن بعض القطع.\r\n2. نفاد الكمية للقطع الأخرى بسبب الإقبال الكبير.\r\n\r\nالإجراء المتخذ: تم خصم قيمة القطع المستبعدة تلقائيًا من إجمالي فاتورة الطلب.\r\n\r\nنأسف لأي إزعاج قد يسببه هذا التغيير و نشكر تفهمك وثقتك.  \r\n\r\nللاطلاع على التفاصيل: يرجى زيارة صفحة طلباتك الخاصة على موقع المتجر.\r\n\r\n{account_portal}', 'order', '', 1, 1, '2026-01-09 22:11:37', '2026-01-09 22:11:37'),
(22, 'بوابة العميل ', 'مرحبا عملينا العزيز: {customer_name}\r\n\r\n🔗 لمتابعة حالة طلبك وتفاصيله عبر رابط حسابك في متجرنا: {account_portal}\r\n', 'general', '', 1, 1, '2026-01-19 15:20:44', '2026-01-19 15:20:44'),
(23, 'قققققق', '{payment_link}', 'order', '', 0, 1, '2026-03-22 06:07:36', '2026-03-22 06:08:27');
